import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { visionScannersRecentObservationsRetrieve } from '../generated/api'
import type { ReplayObservationApi } from '../generated/api.schemas'
import { type ScannersViewMode, replayScannersLogic } from './replayScannersLogic'
import { ReplayScanner } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerHighlightsLogicValues {
    listViewMode: ScannersViewMode // replayScannersLogic
    scanners: ReplayScanner[] // replayScannersLogic
    recentObservations: Record<string, ReplayObservationApi[]> | null
    recentObservationsFailed: boolean
    recentObservationsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerHighlightsLogicActions {
    loadScannersSuccess: (
        scanners: ReplayScanner[],
        total: number
    ) => {
        scanners: ReplayScanner[]
        total: number
    } // replayScannersLogic
    loadRecentObservations: () => {
        value: true
    }
    loadRecentObservationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRecentObservationsSuccess: (
        recentObservations: Record<string, ReplayObservationApi[]>,
        payload?: {
            value: true
        }
    ) => {
        recentObservations: Record<string, ReplayObservationApi[]>
        payload?: {
            value: true
        }
    }
}

export type scannerHighlightsLogicType = MakeLogicType<scannerHighlightsLogicValues, scannerHighlightsLogicActions>

/** Recent-observation previews for the scanners highlights view. Separate from
 * `replayScannersLogic` so the classic list pays nothing for the extra fetch. */
export const scannerHighlightsLogic = kea<scannerHighlightsLogicType>([
    path(['products', 'replay_vision', 'frontend', 'replay_scanners', 'scannerHighlightsLogic']),

    connect(() => ({
        values: [replayScannersLogic, ['scanners', 'listViewMode']],
        actions: [replayScannersLogic, ['loadScannersSuccess']],
    })),

    // Declared here so the action stays zero-arg despite the loader's payload/breakpoint parameters.
    actions({ loadRecentObservations: true }),

    loaders(({ values }) => ({
        recentObservations: [
            null as Record<string, ReplayObservationApi[]> | null,
            {
                loadRecentObservations: async (_, breakpoint) => {
                    const teamId = teamLogic.values.currentTeamId
                    const scannerIds = values.scanners.map((scanner) => scanner.id)
                    if (!teamId || scannerIds.length === 0) {
                        return {}
                    }
                    const response = await visionScannersRecentObservationsRetrieve(String(teamId), {
                        scanner_ids: scannerIds.join(','),
                    })
                    // Drop out-of-order responses — the most recent page change owns the rails.
                    breakpoint()
                    const grouped: Record<string, ReplayObservationApi[]> = {}
                    for (const observation of response.results) {
                        ;(grouped[observation.scanner_id] ??= []).push(observation)
                    }
                    return grouped
                },
            },
        ],
    })),

    reducers({
        recentObservationsFailed: [
            false,
            {
                loadRecentObservations: () => false,
                loadRecentObservationsFailure: () => true,
            },
        ],
    }),

    listeners(({ actions, values }) => ({
        // Refetch per visible page, and only while the highlights view is active — the classic
        // list never triggers this logic's fetch.
        loadScannersSuccess: () => {
            if (values.listViewMode === 'highlights') {
                actions.loadRecentObservations()
            }
        },
    })),

    // Every path into the highlights view reloads scanners, but a remount with scanners already
    // in place (e.g. a kept-alive logic) would otherwise show empty rails.
    afterMount(({ actions, values }) => {
        if (values.listViewMode === 'highlights' && values.scanners.length > 0) {
            actions.loadRecentObservations()
        }
    }),
])
